def check_text(text):
    if re.search('[\u2010-\u2015\u2190-\u21ff\u27f0-\u27ff\u2900-\u297f]|->|<-|=>|<=', text):
        raise ValueError('Forbidden dash or arrow in authored text')

def footer(c, d):
    c.saveState()
    w, h = A4
    c.setStrokeColor(colors.HexColor('#d9e3e8'))
    c.line(44, h-35, w-44, h-35)
    c.setFillColor(colors.HexColor('#596b76'))
    c.setFont('Arial', 8)
    c.drawString(44,h-27,'ИТ в профессиональной деятельности · Тема 2 · 07.11.2026')
    c.drawString(44,25,'Адаменко С. С.')
    c.drawRightString(w-44,25,str(d.page))
    c.restoreState()

def create_all():
    for filename, number, title, pages in DOCS:
        story = []
        md = [f'# Задание {number}. {title.replace(chr(10), " ")}\n', 'Адаменко С. С. · РГПУ им. А. И. Герцена · 07.11.2026\n']
        for idx,page in enumerate(pages):
            if idx:
                story.append(PageBreak())
            else:
                story.append(Paragraph('РГПУ им. А. И. Герцена · Магистратура, 1 курс',styles['meta']))
                story.append(Paragraph(f'Задание {number} · Тема 2. Проф. деятельность в ИОС и ЦОС',styles['meta']))
                story.append(Paragraph(escape(title).replace('\n','<br/>'),styles['title']))
                story.append(Paragraph('Адаменко С. С. · Санкт-Петербург · 2026',styles['meta']))
            for block in page:
                if block[0] == 'table':
                    _,headers,rows,widths = block
                    cells = [[Paragraph(escape(v), styles['headcell']) for v in headers]]
                    cells += [[Paragraph(escape(v),styles['cell']) for v in row] for row in rows]
                    table = Table(cells,colWidths=widths,repeatRows=1,hAlign='LEFT')
                    table.setStyle(TableStyle([
                        ('BACKGROUND',(0,0),(-1,0),BLUE),('VALIGN',(0,0),(-1,-1),'TOP'),
                        ('LEFTPADDING',(0,0),(-1,-1),8),('RIGHTPADDING',(0,0),(-1,-1),8),
                        ('TOPPADDING',(0,0),(-1,-1),8),('BOTTOMPADDING',(0,0),(-1,-1),8),
                        ('ROWBACKGROUNDS',(0,1),(-1,-1),[colors.HexColor('#edf4f6'),colors.HexColor('#f8fafb')]),
                        ('LINEBELOW',(0,0),(-1,0),0.5,BLUE),
                    ]))
                    story.extend([table,Spacer(1,10)])
                    md.append('| '+' | '.join(headers)+' |\n| '+' | '.join(['---']*len(headers))+' |')
                    md.extend('| '+' | '.join(row)+' |' for row in rows)
                    check_text(' '.join(headers)+' '.join(' '.join(r) for r in rows))
                else:
                    kind,text = block
                    # Inspect displayed text only; hyperlink attributes contain ordinary code syntax.
                    plain = re.sub('<[^>]+>','',text)
                    check_text(plain)
                    story.append(Paragraph(text,styles[kind]))
                    md.append(('## ' if kind=='h' else '')+re.sub(r'<link href="([^"]+)" color="[^"]+">(.*?)</link>',r'[\2](\1)',text).replace('<b>','**').replace('</b>','**')+'\n')
        SimpleDocTemplate(str(OUT/filename),pagesize=A4,rightMargin=54,leftMargin=54,topMargin=49,bottomMargin=45,
            title=f'Задание {number}. {title.replace(chr(10), " ")}',author='Адаменко С. С.').build(story,onFirstPage=footer,onLaterPages=footer)
        (ROOT/(filename[:-4]+'.md')).write_text('\n'.join(md),encoding='utf-8')
        print(filename)

if __name__ == '__main__':
    create_all()
